// Node loads PumpSwap's CommonJS build. Its "ESM" build is CommonJS-wrapped code in a .js file with no
// "type" field, so it only loads where Node guesses the module format from the syntax: locally, but
// not on Vercel, where every import of it failed. Browsers resolve #pump-swap-sdk to the package itself
// (see package.json imports).
import { createRequire } from 'node:module'
// Keep `require` a named binding: Vercel's file tracer (@vercel/nft) only follows createRequire when
// its result is assigned to a variable, and would otherwise leave the SDK out of the function bundle.
const require = createRequire(import.meta.url)
const sdk = require('@pump-fun/pump-swap-sdk')
